def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    pairs = []
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r][c] != bg and grid[r][c] == grid[r + 1][nc]:
                    pairs.append((r, c, r + 1, nc, grid[r][c]))

    def occupied_score(r, c, dr, dc):
        score = 0
        for k in range(1, 4):
            rr, cc = r + k * dr, c + k * dc
            if not (0 <= rr < h and 0 <= cc < w):
                break
            if grid[rr][cc] != bg:
                score += 1
        return score

    for r1, c1, r2, c2, color in pairs:
        dr, dc = r2 - r1, c2 - c1
        forward = occupied_score(r2, c2, dr, dc)
        backward = occupied_score(r1, c1, -dr, -dc)
        if forward <= backward:
            rr, cc = r2 + dr, c2 + dc
            sr, sc = dr, dc
        else:
            rr, cc = r1 - dr, c1 - dc
            sr, sc = -dr, -dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += sr
            cc += sc

    # In this pattern a vertical pair of 5s marks a down-left ray.
    if len(pairs) >= 2:
        for r in range(h - 1):
            for c in range(w):
                if grid[r][c] != bg and grid[r][c] == grid[r + 1][c]:
                    color = grid[r][c]
                    if color == 5:
                        rr, cc = r + 2, c - 1
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] == bg:
                                out[rr][cc] = color
                            rr += 1
                            cc -= 1
    return out
